-- Live official course pool: parsed source + typed manual override layer.
alter table public.official_course_schedule_catalog add column if not exists school_subtype text, add column if not exists source_decision_no text, add column if not exists source_decision_date date, add column if not exists source_page smallint, add column if not exists source_section text, add column if not exists parser_confidence numeric(4,3), add column if not exists needs_review boolean not null default false;
alter table public.course_offering_rules add column if not exists school_subtype text;
alter table public.institution_education_units add column if not exists school_subtype text;
alter table public.school_classes add column if not exists school_subtype text;

create table if not exists public.official_curriculum_profiles(id uuid primary key default gen_random_uuid(),effective_academic_year text not null,school_type text not null,school_subtype text,program_type text,field_name text,branch_name text,grade_level smallint not null,required_course_count smallint not null default 0,required_hour_total smallint not null default 0,elective_course_min smallint not null default 0,elective_course_max smallint,elective_hour_min smallint not null default 0,elective_hour_max smallint not null default 0,total_hour_min smallint not null default 0,total_hour_max smallint not null default 0,total_hour_target smallint,group_rules jsonb not null default '[]',source_file_name text,source_decision_no text,source_note text,active boolean not null default true,updated_at timestamptz not null default now(),unique(effective_academic_year,school_type,school_subtype,program_type,field_name,branch_name,grade_level));
create table if not exists public.official_course_schedule_overrides(id uuid primary key default gen_random_uuid(),catalog_id uuid not null unique references public.official_course_schedule_catalog(id) on delete cascade,school_subtype text,program_type text,field_name text,branch_name text,grade_level smallint,category text,hour_options smallint[],max_selections smallint,repeat_across_years boolean,elective_group_key text,source_note text,parsed_constraints jsonb,reason text not null,updated_by uuid default auth.uid(),updated_at timestamptz not null default now(),active boolean not null default true);

alter table public.official_curriculum_profiles enable row level security;alter table public.official_course_schedule_overrides enable row level security;
drop policy if exists official_curriculum_profiles_read on public.official_curriculum_profiles;create policy official_curriculum_profiles_read on public.official_curriculum_profiles for select using(true);
drop policy if exists official_curriculum_profiles_super on public.official_curriculum_profiles;create policy official_curriculum_profiles_super on public.official_curriculum_profiles for all using(is_super_admin()) with check(is_super_admin());
drop policy if exists official_course_schedule_overrides_read on public.official_course_schedule_overrides;create policy official_course_schedule_overrides_read on public.official_course_schedule_overrides for select using(true);
drop policy if exists official_course_schedule_overrides_super on public.official_course_schedule_overrides;create policy official_course_schedule_overrides_super on public.official_course_schedule_overrides for all using(is_super_admin()) with check(is_super_admin());

create or replace view public.official_course_schedule_effective as select c.id,c.effective_academic_year,c.school_type,coalesce(o.school_subtype,c.school_subtype) school_subtype,coalesce(o.program_type,c.program_type) program_type,coalesce(o.field_name,c.field_name) field_name,coalesce(o.branch_name,c.branch_name) branch_name,coalesce(o.grade_level,c.grade_level) grade_level,c.course_id,coalesce(o.category,c.category) category,coalesce(o.hour_options,c.hour_options) hour_options,coalesce(o.max_selections,c.max_selections) max_selections,coalesce(o.repeat_across_years,c.repeat_across_years) repeat_across_years,coalesce(o.elective_group_key,c.elective_group_key) elective_group_key,c.source_file_name,coalesce(o.source_note,c.source_note) source_note,coalesce(o.parsed_constraints,c.parsed_constraints) parsed_constraints,c.source_decision_no,c.source_decision_date,c.source_page,c.source_section,c.parser_confidence,c.needs_review,(o.id is not null and o.active) manually_overridden,c.active from public.official_course_schedule_catalog c left join public.official_course_schedule_overrides o on o.catalog_id=c.id and o.active where c.active;

create or replace function public.super_admin_override_official_course_v1(p_catalog_id uuid,p_patch jsonb,p_reason text) returns void language plpgsql security definer set search_path=public as $$begin if not is_super_admin() then raise exception 'SUPER_ADMIN_REQUIRED';end if;if coalesce(trim(p_reason),'')='' then raise exception 'REASON_REQUIRED';end if;insert into official_course_schedule_overrides(catalog_id,school_subtype,program_type,field_name,branch_name,grade_level,category,hour_options,max_selections,repeat_across_years,elective_group_key,source_note,parsed_constraints,reason,updated_by,updated_at,active) values(p_catalog_id,nullif(p_patch->>'schoolSubtype',''),nullif(p_patch->>'programType',''),nullif(p_patch->>'fieldName',''),nullif(p_patch->>'branchName',''),nullif(p_patch->>'gradeLevel','')::smallint,nullif(p_patch->>'category',''),case when p_patch?'hourOptions' then array(select jsonb_array_elements_text(p_patch->'hourOptions')::smallint) end,nullif(p_patch->>'maxSelections','')::smallint,case when p_patch?'repeatAcrossYears' then (p_patch->>'repeatAcrossYears')::boolean end,nullif(p_patch->>'electiveGroupKey',''),nullif(p_patch->>'sourceNote',''),case when p_patch?'parsedConstraints' then p_patch->'parsedConstraints' end,p_reason,auth.uid(),now(),true) on conflict(catalog_id) do update set school_subtype=excluded.school_subtype,program_type=excluded.program_type,field_name=excluded.field_name,branch_name=excluded.branch_name,grade_level=excluded.grade_level,category=excluded.category,hour_options=excluded.hour_options,max_selections=excluded.max_selections,repeat_across_years=excluded.repeat_across_years,elective_group_key=excluded.elective_group_key,source_note=excluded.source_note,parsed_constraints=excluded.parsed_constraints,reason=excluded.reason,updated_by=auth.uid(),updated_at=now(),active=true;end$$;

create or replace function public.super_admin_upsert_curriculum_profile_v1(p_profile jsonb) returns uuid language plpgsql security definer set search_path=public as $$declare v_id uuid;begin if not is_super_admin() then raise exception 'SUPER_ADMIN_REQUIRED';end if;insert into official_curriculum_profiles(effective_academic_year,school_type,school_subtype,program_type,field_name,branch_name,grade_level,required_course_count,required_hour_total,elective_course_min,elective_course_max,elective_hour_min,elective_hour_max,total_hour_min,total_hour_max,total_hour_target,group_rules,source_file_name,source_decision_no,source_note,active,updated_at) values(p_profile->>'academicYear',p_profile->>'schoolType',nullif(p_profile->>'schoolSubtype',''),nullif(p_profile->>'programType',''),nullif(p_profile->>'fieldName',''),nullif(p_profile->>'branchName',''),(p_profile->>'gradeLevel')::smallint,coalesce((p_profile->>'requiredCourseCount')::smallint,0),coalesce((p_profile->>'requiredHourTotal')::smallint,0),coalesce((p_profile->>'electiveCourseMin')::smallint,0),nullif(p_profile->>'electiveCourseMax','')::smallint,coalesce((p_profile->>'electiveHourMin')::smallint,0),coalesce((p_profile->>'electiveHourMax')::smallint,0),coalesce((p_profile->>'totalHourMin')::smallint,0),coalesce((p_profile->>'totalHourMax')::smallint,0),nullif(p_profile->>'totalHourTarget','')::smallint,coalesce(p_profile->'groupRules','[]'::jsonb),nullif(p_profile->>'sourceFileName',''),nullif(p_profile->>'sourceDecisionNo',''),nullif(p_profile->>'sourceNote',''),true,now()) on conflict(effective_academic_year,school_type,school_subtype,program_type,field_name,branch_name,grade_level) do update set required_course_count=excluded.required_course_count,required_hour_total=excluded.required_hour_total,elective_course_min=excluded.elective_course_min,elective_course_max=excluded.elective_course_max,elective_hour_min=excluded.elective_hour_min,elective_hour_max=excluded.elective_hour_max,total_hour_min=excluded.total_hour_min,total_hour_max=excluded.total_hour_max,total_hour_target=excluded.total_hour_target,group_rules=excluded.group_rules,source_file_name=excluded.source_file_name,source_decision_no=excluded.source_decision_no,source_note=excluded.source_note,active=true,updated_at=now() returning id into v_id;return v_id;end$$;

create or replace function public.sync_official_course_offerings_for_class_v1(p_class_id uuid) returns integer language plpgsql security definer set search_path=public as $$declare c record;v_year text;v_type text;v_field text;v_branch text;v_count int:=0;v_target smallint;begin select s.*,y.code,f.name field_name,b.name branch_name into c from school_classes s join academic_years y on y.id=s.academic_year_id left join institution_fields f on f.id=s.field_id left join institution_branches b on b.id=s.branch_id where s.id=p_class_id and tenant_row_allowed(s.institution_code);if not found then return 0;end if;v_year:=c.code;v_type:=infer_school_type_for_class_v1(c.grade_level,c.program_type,c.school_type);if v_type is null or c.grade_level is null then return 0;end if;v_field:=c.field_name;v_branch:=c.branch_name;update school_classes set school_type=v_type where id=p_class_id and school_type is distinct from v_type;insert into course_offering_rules(institution_code,academic_year,school_level,school_subtype,program_type,field_name,branch_name,grade_level,course_id,category,hour_options,max_selections,repeat_across_years,elective_group_key,source_note,source_file_name,parsed_constraints,active,updated_at) select c.institution_code,v_year,v_type,o.school_subtype,o.program_type,o.field_name,o.branch_name,c.grade_level,o.course_id,o.category,o.hour_options,o.max_selections,o.repeat_across_years,o.elective_group_key,o.source_note,o.source_file_name,o.parsed_constraints,true,now() from official_course_schedule_effective o where o.effective_academic_year=v_year and o.school_type=v_type and o.grade_level=c.grade_level and (o.school_subtype is null or o.school_subtype=c.school_subtype) and (o.program_type is null or o.program_type=c.program_type) and (o.field_name is null or o.field_name=v_field) and (o.branch_name is null or o.branch_name=v_branch) on conflict(institution_code,academic_year,program_type,grade_level,course_id) do update set school_level=excluded.school_level,school_subtype=excluded.school_subtype,field_name=excluded.field_name,branch_name=excluded.branch_name,category=excluded.category,hour_options=excluded.hour_options,max_selections=excluded.max_selections,repeat_across_years=excluded.repeat_across_years,elective_group_key=excluded.elective_group_key,source_note=excluded.source_note,source_file_name=excluded.source_file_name,parsed_constraints=excluded.parsed_constraints,active=true,updated_at=now();get diagnostics v_count=row_count;select coalesce(total_hour_target,total_hour_max,total_hour_min) into v_target from official_curriculum_profiles p where p.active and p.effective_academic_year=v_year and p.school_type=v_type and p.grade_level=c.grade_level and (p.school_subtype is null or p.school_subtype=c.school_subtype) and (p.program_type is null or p.program_type=c.program_type) and (p.field_name is null or p.field_name=v_field) and (p.branch_name is null or p.branch_name=v_branch) order by (p.branch_name is not null)::int desc,(p.field_name is not null)::int desc,(p.program_type is not null)::int desc,(p.school_subtype is not null)::int desc limit 1;if v_target is not null then update school_classes set expected_weekly_hours=v_target where id=p_class_id;end if;return v_count;end$$;

create or replace function public.super_admin_import_official_course_schedule_v2(p_source_file_name text,p_profile jsonb,p_rows jsonb) returns jsonb language plpgsql security definer set search_path=public as $$declare r jsonb;v_course uuid;v_name text;v_hours smallint[];v_count int:=0;v_profile_id uuid;begin if not is_super_admin() then raise exception 'SUPER_ADMIN_REQUIRED';end if;if jsonb_typeof(p_rows)<>'array' then raise exception 'ROWS_MUST_BE_ARRAY';end if;v_profile_id:=super_admin_upsert_curriculum_profile_v1(p_profile||jsonb_build_object('sourceFileName',p_source_file_name));for r in select value from jsonb_array_elements(p_rows) loop v_name:=trim(r->>'courseName');select coalesce(array_agg(distinct x::smallint order by x::smallint),'{}'::smallint[]) into v_hours from jsonb_array_elements_text(coalesce(r->'hourOptions','[]')) x where x::int between 1 and 20;if v_name='' or cardinality(v_hours)=0 then raise exception 'INVALID_OFFICIAL_COURSE_ROW: %',r;end if;insert into course_catalog(code,name,short_name,category,active) values(nullif(trim(r->>'courseCode'),''),v_name,nullif(trim(r->>'shortName'),''),coalesce(nullif(r->>'category',''),'diger'),true) on conflict(name) do update set code=coalesce(excluded.code,course_catalog.code),short_name=coalesce(excluded.short_name,course_catalog.short_name),active=true returning id into v_course;insert into official_course_schedule_catalog(effective_academic_year,school_type,school_subtype,program_type,field_name,branch_name,grade_level,course_id,category,hour_options,max_selections,repeat_across_years,elective_group_key,source_file_name,source_note,parsed_constraints,source_decision_no,source_decision_date,source_page,source_section,parser_confidence,needs_review,active,updated_at) values(p_profile->>'academicYear',p_profile->>'schoolType',nullif(p_profile->>'schoolSubtype',''),nullif(p_profile->>'programType',''),nullif(p_profile->>'fieldName',''),nullif(p_profile->>'branchName',''),(r->>'gradeLevel')::smallint,v_course,coalesce(nullif(r->>'category',''),'diger'),v_hours,coalesce((r->>'maxSelections')::smallint,1),coalesce((r->>'repeatAcrossYears')::boolean,true),nullif(r->>'electiveGroupKey',''),p_source_file_name,nullif(r->>'sourceNote',''),coalesce(r->'parsedConstraints','[]'),nullif(p_profile->>'sourceDecisionNo',''),nullif(p_profile->>'sourceDecisionDate','')::date,nullif(r->>'sourcePage','')::smallint,nullif(r->>'sourceSection',''),nullif(r->>'parserConfidence','')::numeric,coalesce((r->>'needsReview')::boolean,false),true,now()) on conflict(effective_academic_year,school_type,program_type,grade_level,course_id) do update set school_subtype=excluded.school_subtype,field_name=excluded.field_name,branch_name=excluded.branch_name,category=excluded.category,hour_options=excluded.hour_options,max_selections=excluded.max_selections,repeat_across_years=excluded.repeat_across_years,elective_group_key=excluded.elective_group_key,source_file_name=excluded.source_file_name,source_note=excluded.source_note,parsed_constraints=excluded.parsed_constraints,source_decision_no=excluded.source_decision_no,source_decision_date=excluded.source_decision_date,source_page=excluded.source_page,source_section=excluded.source_section,parser_confidence=excluded.parser_confidence,needs_review=excluded.needs_review,active=true,updated_at=now();v_count:=v_count+1;end loop;return jsonb_build_object('profile_id',v_profile_id,'imported_rules',v_count);end$$;